import re
import zipfile

try:
    from defusedxml import minidom
except ImportError:
    from xml.dom import minidom

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

with zipfile.ZipFile('quarterly_report.docx') as z:
    xml = z.read('word/document.xml')

dom = minidom.parseString(xml)


def para_text(p):
    return ''.join(t.firstChild.nodeValue if t.firstChild else '' for t in p.getElementsByTagName('w:t'))


def has_underline(p):
    for r in p.getElementsByTagName('w:r'):
        rpr = None
        for c in r.childNodes:
            if c.nodeType == c.ELEMENT_NODE and c.tagName == 'w:rPr':
                rpr = c
                break
        if rpr is None:
            return False
        us = rpr.getElementsByTagName('w:u')
        if not us or us[0].getAttribute('w:val') != 'single':
            return False
    return True


def is_headline(p):
    txt = para_text(p)
    return bool(txt) and re.search(r'[A-Z]', txt) and not re.search(r'[a-z]', txt)


headlines = [p for p in dom.getElementsByTagName('w:p') if is_headline(p)]

expected = [
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
]
found = [para_text(p) for p in headlines]
assert sorted(found) == sorted(expected), (found, expected)
assert all(has_underline(p) for p in headlines), "Some headline run lacks underline"

print("Verified underlined headlines:", len(headlines))

